namespace PsychologyApp.Application.Articles;

public static partial class ArticleContent
{
    private static readonly Article[] AdditionalArticlesPt =
    [
        MiniArticle(ArticleIds.CallNerves, "Nervosismo antes de uma ligação", "Deixe a primeira ligação mais simples", "Não ensaie a conversa inteira. Anote um objetivo e uma frase para começar. Durante a ligação, você pode consultar a nota, pedir que repitam ou fazer uma pausa. Fazer a ligação já é um sucesso, mesmo sem falar perfeitamente."),
        MiniArticle(ArticleIds.WaitingForReply, "Esperando uma resposta", "O silêncio no chat ainda não explica nada", "Anote três motivos possíveis, incluindo um neutro, e escolha quando olhar de novo. Se for urgente, decida quem contatar e quando, em vez de atualizar a tela sem parar."),
        MiniArticle(ArticleIds.AfterSocialEvent, "Depois de um encontro: pare de repassar cada frase", "Interrompa a repetição mental da conversa", "Lembre um momento que correu bem e uma conclusão que ainda não dá para tirar. Não procure a frase perfeita depois. Volte ao que está fazendo; você pode retomar uma conversa importante mais tarde."),
        MiniArticle(ArticleIds.FearOfMistakes, "Um erro não é uma sentença", "Defina o que é bom o suficiente", "Antes de começar, decida qual resultado basta e confira um requisito importante. Se houver um erro, descubra as consequências reais e o próximo passo que pode ser corrigido. Um deslize não define você por inteiro."),
        MiniArticle(ArticleIds.ChangeAnxiety, "Quando mudanças preocupam", "Separe fatos do que ainda é desconhecido", "Faça duas colunas: o que já sabe e o que pode descobrir. Escolha uma pergunta e um momento para retomá-la. O restante pode esperar; incerteza não significa que algo ruim vai acontecer."),
        MiniArticle(ArticleIds.WorryBeforeTask, "Antes de uma tarefa difícil", "Comece sem exigir confiança total", "Decida o que precisa para começar com segurança: materiais, dez minutos ou um esclarecimento. Comece só por isso e depois decida se continua. Você não precisa esperar a ansiedade sumir."),
        MiniArticle(ArticleIds.AvoidedFirstStep, "Dê apenas o primeiro passo", "O começo pode levar dois minutos", "Faça o início ficar pequeno: abra o arquivo, escreva um título ou separe os materiais. Depois, você pode parar. A ideia é facilitar o começo, não tirar seu direito a uma pausa."),
        MiniArticle(ArticleIds.CheckingLoop, "Confira e depois pare", "Defina um limite antes de conferir", "Decida o que vai conferir e quantas vezes. Depois da última, marque como concluída e passe para outra coisa. Se a ansiedade pedir mais uma checagem, reconheça isso como um pedido da ansiedade, não como um fato novo."),
        MiniArticle(ArticleIds.PublicPlaceAnxiety, "Ansiedade em um lugar público", "Encontre um apoio e mantenha a possibilidade de escolha", "Sinta o chão sob os pés e nomeie alguns objetos ao redor. Procure um local mais tranquilo. Você pode sair ou pedir ajuda se não estiver seguro; um exercício não deve obrigar você a ficar."),
        MiniArticle(ArticleIds.MorningWorry, "Uma manhã sem lista de preocupações", "Você não precisa resolver a semana antes do café", "Anote as preocupações e marque uma necessidade real para hoje. Agende o restante ou espere novas informações. Comece com um passo, sem tentar prever tudo."),
        MiniArticle(ArticleIds.SensoryOverload, "Quando há barulho e tarefas demais", "Reduza a carga sobre sua atenção", "Se puder, retire uma fonte de ruído, diminua o brilho da tela ou vá a um lugar mais silencioso. Escolha um ponto de apoio para a atenção. Uma pausa não obriga você a voltar logo ao ritmo anterior."),
        MiniArticle(ArticleIds.EveningTension, "Encerre o dia com gentileza", "Passe as tarefas inacabadas para amanhã", "Reserve alguns minutos para anotar o que foi feito, o que pode esperar e por onde começar amanhã. Se a rotina mudou, escolha uma deixa simples para dormir em vez de um ritual rígido."),
        MiniArticle(ArticleIds.AnxietyComedown, "Depois de uma onda de ansiedade", "Recupere-se primeiro; reflita depois", "Confira se você está seguro e dê a si mesmo tempo para voltar ao seu ritmo. Uma atividade simples e conhecida pode ajudar. Mais tarde, anote o que ajudou e o que gostaria de conversar com um profissional."),
        MiniArticle(ArticleIds.SafePractice, "Uma prática não é uma prova", "Adapte o exercício a você", "Você pode encurtar, manter os olhos abertos, pular uma etapa ou parar. Se ficar desconfortável, volte à respiração natural e escolha outro apoio. Não é preciso suportar desconforto para seguir uma instrução."),

        MiniArticle(ArticleIds.ThoughtLabel, "Dê um nome ao pensamento", "Perceba-o sem discutir", "Experimente: «Estou percebendo o pensamento de que…». Isso não prova que ele seja falso, mas ajuda a vê-lo como pensamento. Depois pergunte que pequena ação combina agora com sua tarefa ou seus valores."),
        MiniArticle(ArticleIds.MindReading, "Não tente adivinhar o que os outros pensam", "Separe o que observou do que imaginou", "Anote o que a pessoa disse ou fez literalmente e depois o que você interpretou. Se a resposta importa, pergunte com calma. Se não, deixe a dúvida em aberto em vez de tratar uma suposição como fato."),
        MiniArticle(ArticleIds.WorstVsLikely, "O pior resultado não é o mais provável", "Considere mais de uma possibilidade", "Anote o pior resultado, o melhor e o mais plausível. Prepare-se para o plausível; para o pior, basta um plano razoável de segurança se necessário. Não gaste toda a energia detalhando cada cenário imaginado."),
        MiniArticle(ArticleIds.EvidenceAndUnknown, "O que sei e o que ainda não sei", "Não preencha uma lacuna com uma suposição ansiosa", "Faça duas colunas: «Eu sei» e «Ainda não sei». Para o desconhecido, escolha como obter informação ou quando rever a questão. Se não for possível descobrir agora, deixe-a em aberto."),
        MiniArticle(ArticleIds.NegativityFilter, "Perceba também o que deu certo", "Acrescente mais um fato ao quadro", "Depois de algo difícil, a mente pode notar erros e ignorar momentos comuns ou bons. Nomeie um fato que não combina com a versão negativa. Não precisa fingir que tudo está bem; basta enxergar o conjunto."),
        MiniArticle(ArticleIds.ConversationReplay, "Pare de repassar a conversa sem parar", "Decida se existe um próximo passo", "Pergunte se há um problema específico que você possa reparar. Se sim, anote um próximo passo curto. Se não, reconheça a repetição e volte ao que vê, ouve ou faz agora."),
        MiniArticle(ArticleIds.DecisionFatigue, "Simplifique uma escolha pequena", "Decida antes o que é suficiente", "Para escolhas pequenas e repetidas, use uma regra simples: orçamento, tempo ou um critério de qualidade. Aplique-a sem comparar todas as opções para sempre. Reserve tempo e dados para decisões importantes."),
        MiniArticle(ArticleIds.GoodEnough, "Bom o suficiente também é resultado", "Limite os retoques desnecessários", "Defina dois requisitos que o resultado deve cumprir e um horário para parar. Quando estiverem atendidos, salve ou envie. Faça mais ajustes apenas para resolver algo concreto, não para buscar perfeição impossível."),
        MiniArticle(ArticleIds.ControlInfluence, "O que posso influenciar e o que não posso", "Concentre-se em uma ação disponível", "Desenhe dois círculos: o que depende de você e o que não depende. Escolha um passo no primeiro; para o outro, pense em limite, apoio ou tolerar a incerteza. Isso não apaga injustiças nem restrições reais."),
        MiniArticle(ArticleIds.SelfTalkReset, "Mude o tom da conversa consigo", "Fale consigo com respeito e clareza", "Troque «estraguei tudo de novo» por uma ação: «Perdi o prazo; vou perguntar o que ainda pode ser corrigido». Isso não desculpa o erro, mas ajuda a seguir sem se insultar."),
        MiniArticle(ArticleIds.WorryAboutWorry, "Preocupar-se por estar preocupado", "Não exija que a calma chegue na hora", "Quando pensar «não deveria me sentir assim», chame isso de uma segunda onda de preocupação. Deixe a primeira reação existir e volte à tarefa mais próxima. Se a ansiedade atrapalha muito, converse com um profissional."),
        MiniArticle(ArticleIds.CompareHighlightReel, "Não compare sua vida com a vitrine de alguém", "A rede mostra momentos escolhidos, não uma vida inteira", "Lembre que uma publicação é só um recorte. Se a comparação piorar seu humor, faça uma pausa e escolha seu próprio parâmetro: o que importa para você, não o que parece impressionante."),
        MiniArticle(ArticleIds.IntrusiveThoughts, "Um pensamento indesejado não é uma intenção", "Observe ações e contexto, não só o pensamento", "Um pensamento perturbador pode assustar por não combinar com seus desejos. Você não precisa se testar o tempo todo. Perceba-o e volte à tarefa escolhida; se atrapalhar muito, procure apoio profissional."),
        MiniArticle(ArticleIds.OneThingAtATime, "Uma tarefa de cada vez", "Reduza o custo de mudar de foco", "Anote o que precisa de atenção e escolha uma tarefa por um período curto. Feche abas ou avisos desnecessários, se puder. As outras tarefas não sumiram; só estão esperando sua vez."),

        MiniArticle(ArticleIds.MoodMovement, "Um pouco de movimento quando falta energia", "A ação não precisa esperar o humor melhorar", "Escolha um movimento acessível por alguns minutos: alongar, andar pelo cômodo ou olhar para fora. Perceba como fica depois. É um experimento, não uma obrigação de se exercitar ou sentir-se melhor."),
        MiniArticle(ArticleIds.PleasureMastery, "Prazer e sensação de conclusão", "Perceba diferentes tipos de atividade que ajudam", "Você pode planejar uma atividade agradável e uma pequena tarefa que dê sensação de conclusão. Elas podem ser a mesma. Se não acontecer, isso informa sobre sua carga; não é motivo para se culpar."),
        MiniArticle(ArticleIds.EnergyBudget, "Distribua energia, não só o tempo", "Deixe espaço para se recuperar", "Marque as tarefas que exigem mais energia. Se possível, coloque uma pausa curta ou uma tarefa mais leve entre elas. Um plano com margem costuma ser mais realista do que uma agenda sem intervalos."),
        MiniArticle(ArticleIds.RestBreak, "Faça uma pausa sem culpa", "O descanso pode ajudar na próxima escolha", "Escolha uma pausa curta e algo que seja descanso para você: silêncio, água, alongamento ou olhar ao longe. Não transforme a pausa em outra tarefa. Se a carga não permite descansar, disciplina não é o único problema."),
        MiniArticle(ArticleIds.StartFriction, "Remova um obstáculo antes de começar", "Prepare o início com antecedência", "Perceba o que costuma dificultar o começo: procurar um arquivo, muitos passos ou uma tarefa vaga. Prepare só o próximo item: abra o documento, separe o material ou escreva a primeira pergunta."),
        MiniArticle(ArticleIds.TransitionRitual, "Passe de uma tarefa para outra", "Uma pausa curta esclarece o próximo passo", "Antes da próxima tarefa, pare por um minuto: feche o arquivo anterior, anote o que falta e nomeie o que vem agora. Não é um ritual obrigatório nem uma regra de produtividade, apenas uma transição clara."),
        MiniArticle(ArticleIds.TaskActivation, "Quando é difícil começar", "A ação pode vir antes da motivação", "Escolha uma ação visível que leve menos de cinco minutos; use um cronômetro só se ajudar. Quando terminar, decida se continua. A motivação pode aparecer depois, mas você não precisa se forçar."),
        MiniArticle(ArticleIds.GentleRoutine, "Uma rotina flexível, não perfeita", "Mantenha um ponto estável no dia", "Escolha uma deixa pequena e repetível, como planejar depois do café da manhã. Se o horário mudar, mantenha a sequência, não o minuto exato. Perder um dia não impede retomar o hábito."),
        MiniArticle(ArticleIds.WakeAtNight, "Se acordar durante a noite", "Mantenha o ambiente calmo e evite olhar o relógio", "Tente não avaliar a noite minuto a minuto. Se ficar na cama for desagradável, faça por um tempo uma atividade tranquila com luz baixa e volte quando sentir sono. Se o problema persistir, converse com um profissional de saúde."),
        MiniArticle(ArticleIds.SmallDayPlan, "Um plano diário com espaço", "Escolha o principal e deixe margem para imprevistos", "Anote uma tarefa importante, uma pequena e uma pausa. O restante é opcional se houver tempo e energia. Você pode mudar o plano; ser flexível não significa decepcionar a si mesmo."),
        MiniArticle(ArticleIds.AskForHelpTask, "Peça ajuda em uma parte específica", "Um pedido claro reduz as suposições", "Em vez de «me ajuda», diga uma ação e um prazo: «Você pode revisar este parágrafo hoje?» Explique o que seria útil. Fica mais fácil responder e perceber se a ajuda serve."),
        MiniArticle(ArticleIds.MeaningfulActivity, "Uma atividade que importa para você", "Ligue um pequeno passo a um valor", "Pergunte o que importa nesta situação: cuidado, curiosidade, responsabilidade ou descanso. Escolha uma ação pequena nessa direção. Ela pode ter sentido mesmo sem mudar toda a situação de uma vez."),
        MiniArticle(ArticleIds.FlexibleGoals, "Mude o plano sem abandonar o objetivo", "Ajuste o passo à energia de hoje", "Se o plano original for grande demais, reduza o volume ou mude o método. Mantenha a direção, não necessariamente a forma: dez minutos em vez de uma hora, ou um rascunho em vez de algo perfeito. A meta pode ser flexível."),
        MiniArticle(ArticleIds.CelebrateCompletion, "Perceba o que você já fez", "A mente costuma pular para a próxima tarefa", "Ao terminar, nomeie brevemente o que fez e o esforço envolvido. Não precisa de recompensa; perceber o fato já basta. Assim você enxerga também o que concluiu, não só o que falta."),

        MiniArticle(ArticleIds.NameEmotion, "Dê um nome mais preciso ao sentimento", "Uma palavra pode ajudar a escolher uma resposta", "Em vez de «estou mal», tente uma palavra mais específica: tenso, decepcionado, com medo ou cansado. Pode haver dúvida; isto não é um teste. Pergunte depois do que precisa: segurança, pausa, clareza ou contato."),
        MiniArticle(ArticleIds.MixedFeelings, "Dois sentimentos diferentes podem coexistir", "Sentimentos mistos não tornam você incoerente", "Você pode estar feliz com uma mudança e sentir falta do que havia antes. Nomeie os dois lados sem se obrigar a escolher. Pergunte qual precisa de atenção agora e ofereça um pequeno cuidado."),
        MiniArticle(ArticleIds.AngerPause, "Faça uma pausa antes de responder com raiva", "Segurança primeiro, palavras depois", "Se a conversa estiver escalando, proponha uma pausa e diga quando pode retomá-la. Vá para um lugar seguro e dê tempo a si mesmo. Se houver risco de violência, procure proteção e ajuda."),
        MiniArticle(ArticleIds.ShameKindness, "Responda à vergonha sem se humilhar", "Você pode reparar um erro sem se punir", "Diga a si: «Estou com vergonha agora, mas este sentimento não me descreve por inteiro». Separe a ação da identidade: o que aconteceu e há algo a reparar? Escolha a resposta que ofereceria a alguém querido."),
        MiniArticle(ArticleIds.GuiltRepair, "Culpa: reparar algo ou deixar passar", "Separe responsabilidade de autocobrança sem fim", "Se você causou dano, pense em uma reparação concreta e um pedido de desculpas respeitoso. Se não houve uma transgressão real, a culpa pode ser um sentimento, não uma prova. Punir-se sem parar não ajuda quem foi ferido."),
        MiniArticle(ArticleIds.EnvyInformation, "A inveja pode indicar o que você deseja", "Transforme comparação em uma direção própria", "Pergunte o que inveja: liberdade, reconhecimento, proximidade ou habilidade? Isso não faz de você uma pessoa ruim. Dê um pequeno passo em direção à sua necessidade, sem copiar a vida de outra pessoa."),
        MiniArticle(ArticleIds.AllowSadness, "A tristeza não precisa sumir agora", "Dê espaço ao sentimento e escolha apoio", "Nomeie a perda ou decepção sem se obrigar a ficar bem. Pergunte o que seria gentil agora: ficar só, escrever a alguém próximo ou fazer uma tarefa necessária. Se atrapalhar sua vida por muito tempo, procure ajuda."),
        MiniArticle(ArticleIds.Numbness, "Quando é difícil sentir alguma coisa", "Não se force a se abrir de uma vez", "A sensação de entorpecimento pode aparecer com sobrecarga, mas não explica a causa. Comece por algo neutro: onde está, o que vê e o que quer nos próximos dez minutos. Se isso preocupa ou persiste, converse com um profissional."),
        MiniArticle(ArticleIds.EmotionWave, "Um sentimento pode mudar, mesmo que não de imediato", "Observe sem cronômetro", "Avalie o sentimento de zero a dez e dê um nome a ele. Você pode conferir depois sem exigir que diminua. O objetivo é notar mudanças e manter opções, não medir quanto demora para se acalmar."),
        MiniArticle(ArticleIds.BodyNoticingChoice, "Perceba o corpo em um ritmo confortável", "Um apoio externo também é uma opção", "Se notar sensações do corpo for desagradável, não se force. Olhe para um objeto estável, sinta o apoio da cadeira ou nomeie os sons. Atenção ao corpo é uma opção, não uma exigência da autoajuda."),
        MiniArticle(ArticleIds.PauseBeforeReact, "Faça uma pausa entre impulso e ação", "Escolha uma resposta que talvez gere menos arrependimento", "Se quiser enviar uma mensagem na hora, espere alguns minutos se for seguro. Nomeie o objetivo e mantenha só as palavras necessárias. Se esperar puder prejudicar, aja; a pausa deve ajudar, não atrapalhar."),
        MiniArticle(ArticleIds.EmotionalBoundary, "Os sentimentos dos outros não são seus para consertar", "Você pode se importar e manter limites", "Você pode ouvir sem concordar com tudo ou prometer resolver o problema. Pergunte se a pessoa quer apoio ou conselho e diga o que pode oferecer. Empatia não exige abandonar suas necessidades."),
        MiniArticle(ArticleIds.FeelingNotAction, "Um sentimento não exige uma ação", "Existe escolha entre emoção e comportamento", "Você pode sentir raiva sem ofender, medo e pedir uma pausa ou ciúme sem conferir mensagens. Nomeie o impulso e escolha uma ação que considere seu sentimento e a segurança dos outros."),
        MiniArticle(ArticleIds.AfterCrying, "Depois de chorar", "Cuide do próximo minuto", "Você pode lavar o rosto, sentar em silêncio, respirar normalmente, pedir água ou falar com alguém próximo. Não precisa explicar o choro agora. Se estiver em perigo ou não conseguir se manter seguro, procure ajuda urgente."),

        MiniArticle(ArticleIds.SpecificRequest, "Peça algo específico", "Um pedido claro deixa espaço para uma resposta", "Diga o que aconteceu, do que precisa e para quando. Por exemplo: «Não consigo preparar os materiais a tempo; você pode cuidar desta parte até sexta?» A outra pessoa pode dizer não; você pode procurar outra opção."),
        MiniArticle(ArticleIds.ListenReflect, "Entenda primeiro, responda depois", "Uma breve confirmação pode reduzir a tensão", "Repita com suas palavras o que entendeu e pergunte se está correto. Não dê conselhos sem que peçam. Mesmo discordando, você pode mostrar que ouviu a mensagem."),
        MiniArticle(ArticleIds.BoundarySentence, "Uma frase para colocar um limite", "Uma resposta curta costuma ser mais clara que uma longa defesa", "Tente: «Não posso assumir isso agora» ou «Esse tom não me faz bem; continuo quando pudermos conversar com calma». Adapte às circunstâncias e à segurança. Um limite diz o que você fará, não o que a outra pessoa deve fazer."),
        MiniArticle(ArticleIds.NoWithoutEssay, "Você pode dizer não sem uma longa explicação", "Escolha uma frase educada e clara", "Diga «Obrigado, mas não posso» ou «Isso não funciona para mim». Ofereça uma alternativa só se quiser. Em uma situação insegura, uma recusa direta pode não ser a melhor escolha; priorize sua proteção."),
        MiniArticle(ArticleIds.DifficultTalkOpening, "Comece uma conversa difícil com um objetivo", "Fale de um episódio e de um pedido", "Escolha um momento tranquilo, nomeie uma situação concreta e diga o que gostaria de mudar. Por exemplo: «Fica difícil quando os planos mudam sem aviso; podemos avisar antes?» Não comece se isso não for seguro."),
        MiniArticle(ArticleIds.RepairAfterConflict, "Retome a conversa depois de uma discussão", "Dê um pequeno passo para esclarecer", "Quando ambos estiverem prontos, diga qual foi sua parte e pergunte como a outra pessoa viu a situação. Não é preciso resolver tudo de uma vez. Se voltar a ficar inseguro, pare e procure apoio."),
        MiniArticle(ArticleIds.ApologyResponsibility, "Peça desculpas sem abrir mão dos seus limites", "Nomeie a ação e o que vai mudar", "Um pedido de desculpas útil é específico: «Interrompi você; da próxima vez vou ouvir». Não acrescente «mas você…» na mesma frase. Reconhecer um erro não exige aceitar toda acusação nem abrir mão da segurança."),
        MiniArticle(ArticleIds.FeedbackAsInformation, "Separe uma crítica do seu valor", "Esclareça o que pode ser útil", "Identifique a ação concreta que pode mudar e peça um exemplo se não estiver clara. Um resultado não avalia você por inteiro. Insultos não viram feedback útil só por serem chamados de crítica."),
        MiniArticle(ArticleIds.ReceiveNo, "Quando alguém diz não", "Recusar um pedido nem sempre é rejeitar você", "Separe a resposta a um pedido específico da conclusão que tira sobre si. Se fizer sentido, pergunte sobre outro horário ou opção. Você pode se decepcionar e ainda buscar apoio em outro lugar."),
        MiniArticle(ArticleIds.CheckAssumption, "Confira uma suposição com uma pergunta", "Esclareça o sentido antes de criar uma história", "Se a mensagem for ambígua, pergunte com neutralidade: «Entendi corretamente que…?» Isso ajuda mais que responder a um subtexto imaginado. Se não puder perguntar, separe fato de suposição e espere antes de concluir."),
        MiniArticle(ArticleIds.AskSupport, "Pedir apoio é uma habilidade", "Diga o que ajudaria", "Você pode pedir que alguém escute, caminhe junto ou ajude em uma tarefa. Diga se quer ideias ou só companhia. Se a pessoa não puder ajudar, isso não prova que suas necessidades são exageradas."),
        MiniArticle(ArticleIds.SupportWithoutFixing, "Esteja presente sem resolver tudo", "Pergunte que apoio seria útil", "Tente: «Você quer que eu escute, fique com você ou ajude a pensar no próximo passo?» Não prometa o que não pode cumprir. O apoio respeita as escolhas da outra pessoa e seus próprios limites."),
        MiniArticle(ArticleIds.ConflictNotFailure, "Um conflito nem sempre significa o fim da relação", "Observe como vocês se tratam", "Também importam o respeito, a possibilidade de pausar e a disposição para falar do impacto. Você não precisa tolerar ameaças ou violência para «salvar a relação»; segurança vem primeiro."),
        MiniArticle(ArticleIds.MakeExpectationsClear, "Fale das expectativas antes", "Não espere que a outra pessoa adivinhe", "Antes de uma atividade conjunta, esclareça prazos, papéis e o que significa terminar. Confira se entenderam o combinado da mesma forma. Clareza não garante acordo, mas mostra diferenças mais cedo."),
        MiniArticle(ArticleIds.DigitalBoundaries, "Limites nas mensagens", "Notificações não precisam comandar seu dia", "Escolha quando responder e desligue avisos não essenciais se fizer sentido. Você pode contar a pessoas próximas quando costuma estar disponível. Mantenha outra forma clara de contato para urgências."),
        MiniArticle(ArticleIds.FamilyPressure, "Quando a família insiste com conselhos", "Agradeça e diga que você vai decidir", "Tente: «Vejo que você está preocupado. Vou pensar e decidir». Se a conversa continuar, repita a frase ou mude de assunto. Use essa abordagem apenas se ela não aumentar seu risco."),
        MiniArticle(ArticleIds.FriendshipInvitation, "Convide alguém sem fazer um grande plano", "Um convite pequeno é mais fácil de aceitar ou recusar", "Faça um convite concreto e sem pressão: «Quer caminhar na quinta depois do trabalho?» Acrescente que outro horário ou um não também está tudo bem. A resposta mostra a disponibilidade da pessoa agora, não seu valor."),
        MiniArticle(ArticleIds.SmallConnection, "Um contato pequeno também conta", "Você não precisa começar com uma conversa profunda", "Se sentir solidão, escolha um jeito fácil de estar com pessoas: uma mensagem curta, um lugar conhecido ou conversa neutra. Pare quando bastar. O objetivo é experimentar conexão, não se forçar a ser sociável."),

        MiniArticle(ArticleIds.OrientNow, "Confira onde você está agora", "Uma forma gentil de se orientar no presente", "Olhe ao redor e nomeie o lugar, a data ou parte do dia, alguns objetos e o que acontece agora. Mantenha os olhos abertos e vá no seu ritmo. Se aumentar a ansiedade, escolha um objeto neutro ou peça apoio."),
